import{_ as s,a0 as r,w as o,s as p,ao as e,I as x,x as i,a1 as u,A as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const D=JSON.parse('{"title":"Linux vs. Unix：有什麼不同？ | LCTT x X-CMD","titleTemplate":false,"description":"Linux vs. Unix：有什麼不同？ | LCTT (201806) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux vs. Unix：有什麼不同？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux vs. Unix：有什麼不同？ | LCTT (201806) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201806/20180521 Linux vs. Unix- What-s the difference","title":"Linux vs. Unix：有什麼不同？","tag":"201806","desc":""},"relativePath":"201806/20180521 Linux vs. Unix- What-s the difference.md","filePath":"[post].md"}'),U={name:"201806/20180521 Linux vs. Unix- What-s the difference.md"};function d(L,n,S,f,a,m){const t=r("Link");return o(),p("div",null,[n[36]||(n[36]=e('<h1 id="linux-vs-unix-有什麼不同" tabindex="-1">Linux vs. Unix：有什麼不同？ <a class="header-anchor" href="#linux-vs-unix-有什麼不同" aria-label="Permalink to “Linux vs. Unix：有什麼不同？”">​</a></h1><blockquote><p>深入瞭解這兩個有許多共同的傳統和相同的目標的操作系統之間的不同。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/BUSINESS_twoforward.png?itok=exkV49ts" alt=""></p><p>如果你是位二、三十歲的軟件開發人員，那麼你已經成長在一個由 Linux 主導的世界。數十年來，它一直是數據中心的重要參與者，儘管很難找到明確的操作系統市場份額報告，但 Linux 的數據中心操作系統份額可能高達 70%，而 Windows 及其變體幾乎涵蓋了所有剩餘的百分比。使用任何主流公共雲服務的開發人員都可以預期目標系統會運行 Linux。近些年來，隨着 Android 和基於 Linux 的嵌入式系統在智能手機、電視、汽車和其他設備中的應用，Linux 已經隨處可見。</p><p>即便如此，大多數軟件開發人員，甚至是那些在這場歷史悠久的 “Linux 革命”中長大的軟件開發人員，也都聽過説 Unix。它聽起來與 Linux 相似，你可能已經聽到人們互換使用這些術語。或者你也許聽説過 Linux 被稱為“類 Unix ”操作系統。</p><p>那麼，Unix 是什麼？漫畫中提到了像巫師一樣留着“灰鬍子”，坐在發光的綠色屏幕後面，寫着 C 代碼和 shell 腳本，由老式的、滴灌的咖啡提供動力。但是，Unix 的歷史比上世紀 70 年代那些留着鬍子的 C 程序員要豐富得多。雖然詳細介紹 Unix 歷史和 “Unix 與 Linux” 比較的文章比比皆是，但本文將提供高級背景和列出這些互補世界之間的主要區別。</p><h3 id="unix-的起源" tabindex="-1">Unix 的起源 <a class="header-anchor" href="#unix-的起源" aria-label="Permalink to “Unix 的起源”">​</a></h3>',7)),x("p",null,[n[1]||(n[1]=i("Unix 的歷史始於 20 世紀 60 年代後期的 AT&T 貝爾實驗室，有一小組程序員希望為 PDP-7 編寫一個多任務、多用户操作系統。這個貝爾實驗室研究機構的團隊中最著名的兩名成員是 Ken Thompson 和 Dennis Ritchie。儘管 Unix 的許多概念都是其前身（",-1)),u(t,{href:"https://en.wikipedia.org/wiki/Multics"},{default:l(()=>[...n[0]||(n[0]=[i("Multics",-1)])]),_:1}),n[2]||(n[2]=i("）的衍生物，但 Unix 團隊早在 70 年代就決定用 C 語言重寫這個小型操作系統，這是將 Unix 與其他操作系統區分開來的原因。當時，操作系統很少，更不要説可移植的操作系統。相反，由於它們的設計和底層語言的本質，操作系統與他們所編寫的硬件平台緊密相關。而通過 C 語言重構 Unix、Unix 現在可以移植到許多硬件體系結構中。",-1))]),x("p",null,[n[4]||(n[4]=i("除了這種新的可移植性，之所以使得 Unix 迅速擴展到貝爾實驗室以外的其他研究和學術機構甚至商業用途，是因為操作系統設計原則的幾個關鍵點吸引了用户和程序員們。首先是 Ken Thompson 的 ",-1)),u(t,{href:"https://en.wikipedia.org/wiki/Unix_philosophy"},{default:l(()=>[...n[3]||(n[3]=[i("Unix 哲學",-1)])]),_:1}),n[5]||(n[5]=i("成為模組化軟件設計和計算的強大模型。Unix 哲學推薦使用小型的、專用的程序組合起來完成複雜的整體任務。由於 Unix 是圍繞文件和管道設計的，因此這種“管道”模式的輸入和輸出程序的組合成一組線性的輸入操作，現在仍然流行。事實上，目前的雲功能即服務（FaaS）或無服務器計算模型要歸功於 Unix 哲學的許多傳統。",-1))]),n[37]||(n[37]=e('<h3 id="快速增長和競爭" tabindex="-1">快速增長和競爭 <a class="header-anchor" href="#快速增長和競爭" aria-label="Permalink to “快速增長和競爭”">​</a></h3><p>到 70 年代末和 80 年代，Unix 成為了一個操作系統家族的起源，它遍及了研究和學術機構以及日益增長的商業 Unix 操作系統業務領域。Unix 不是開源軟件，Unix 源代碼可以通過與它的所有者 AT&amp;T 達成協議來獲得許可。第一個已知的軟件許可證於 1975 年出售給<ruby>伊利諾伊大學<rt>University of Illinois</rt></ruby>。</p><p>Unix 在學術界迅速發展，在 Ken Thompson 在上世紀 70 年代的學術假期間，伯克利成為一個重要的活動中心。通過在伯克利的各種有關 Unix 的活動，Unix 軟件的一種新的交付方式誕生了：<ruby>伯克利軟件發行版<rt>Berkeley Software Distribution</rt></ruby>（BSD）。最初，BSD 不是 AT&amp;T Unix 的替代品，而是一種添加類似於附加軟件和功能。在 1979 年， 2BSD（第二版伯克利軟件發行版）出現時，伯克利研究生 Bill Joy 已經添加了現在非常有名的程序，例如 <code>vi</code> 和 C shell（<code>/bin/csh</code>）。</p>',3)),x("p",null,[n[7]||(n[7]=i("除了成為 Unix 家族中最受歡迎的分支之一的 BSD 之外，Unix 的商業產品的爆發貫穿了二十世紀八、九十年代，其中包括 HP-UX、IBM 的 AIX、 Sun 的 Solaris、 Sequent 和 Xenix 等。隨着分支從根源頭髮展壯大，“",-1)),u(t,{href:"https://en.wikipedia.org/wiki/Unix_wars"},{default:l(()=>[...n[6]||(n[6]=[i("Unix 戰爭",-1)])]),_:1}),n[8]||(n[8]=i("”開始了，標準化成為社區的新焦點。POSIX 標準誕生於 1988 年，其他標準化後續工作也開始通過 The Open Group 在 90 年代到來。",-1))]),x("p",null,[n[10]||(n[10]=i("在此期間，AT&T 和 Sun 發佈了 System V Release 4（SVR4），許多商業供應商都採用了這一版本。另外，BSD 系列操作系統多年來一直在增長，最終一些開源的變體在現在熟悉的 ",-1)),u(t,{href:"https://en.wikipedia.org/wiki/BSD_licenses"},{default:l(()=>[...n[9]||(n[9]=[i("BSD許可證",-1)])]),_:1}),n[11]||(n[11]=i("下發布。這包括 FreeBSD、 OpenBSD 和 NetBSD，每個在 Unix 服務器行業的目標市場略有不同。這些 Unix 變體今天仍然有一些在使用，儘管人們已經看到它們的服務器市場份額縮小到個位數字（或更低）。在當今的所有 Unix 系統中，BSD 可能擁有最大的安裝基數。另外，每台 Apple Mac 硬件設備從歷史的角度看都可以算做是 BSD ，這是因為 OS X（現在是 macOS）操作系統是 BSD 衍生產品。",-1))]),n[38]||(n[38]=x("p",null,"雖然 Unix 的全部歷史及其學術和商業變體可能需要更多的篇幅，但為了我們文章的重點，讓我們來討論 Linux 的興起。",-1)),n[39]||(n[39]=x("h3",{id:"進入-linux",tabindex:"-1"},[i("進入 Linux "),x("a",{class:"header-anchor",href:"#進入-linux","aria-label":"Permalink to “進入 Linux”"},"​")],-1)),x("p",null,[n[13]||(n[13]=i("今天我們所説的 Linux 操作系統實際上是 90 年代初期的兩個努力的結合。Richard Stallman 希望創建一個真正的自由而開放源代碼的專有 Unix 系統的替代品。他正在以 GNU 的名義開發實用程序和程序，這是一種遞歸的説法，意思是“GNU‘s not Unix!”。雖然當時有一個內核項目正在進行，但事實證明這是一件很困難的事情，而且沒有內核，自由和開源操作系統的夢想無法實現。而這是 Linus Torvald 的工作 —— 生產出一種可工作和可行的內核，他稱之為 Linux -- 它將整個操作系統帶入了生活。鑑於 Linus 使用了幾個 GNU 工具（例如 GNU 編譯器集合，即 ",-1)),u(t,{href:"https://en.wikipedia.org/wiki/GNU_Compiler_Collection"},{default:l(()=>[...n[12]||(n[12]=[i("GCC",-1)])]),_:1}),n[14]||(n[14]=i("），GNU 工具和 Linux 內核的結合是完美的搭配。",-1))]),n[40]||(n[40]=x("p",null,"Linux 發行版採用了 GNU 的組件、Linux 內核、MIT 的 X-Windows GUI 以及可以在開源 BSD 許可下使用的其它 BSD 組件。像 Slackware 和 Red Hat 這樣的發行版早期的流行給了 20 世紀 90 年代的“普通 PC 用户”一個進入 Linux 操作系統的機會，並且讓他們在工作和學術生活中可以使用許多 Unix 系統特有的功能和實用程序。",-1)),x("p",null,[n[16]||(n[16]=i("由於所有 Linux 組件都是自由和開放的源代碼，任何人都可以通過一些努力來創建一個 Linux 發行版，所以不久後發行版的總數達到了數百個。今天，",-1)),u(t,{href:"https://distrowatch.com/"},{default:l(()=>[...n[15]||(n[15]=[i("distrowatch.com",-1)])]),_:1}),n[17]||(n[17]=i(" 列出了 312 種各種形式的獨特的 Linux 發行版。當然，許多開發人員通過雲提供商或使用流行的免費發行版來使用 Linux，如 Fedora、 Canonical 的 Ubuntu、 Debian、 Arch Linux、 Gentoo 和許多其它變體。隨着包括 IBM 在內的許多企業從專有 Unix 遷移到 Linux 上並提供了中間件和軟件解決方案，商用 Linux 產品在自由和開源組件之上提供支持變得可行。紅帽公司圍繞 Red Hat Enterprise Linux（紅帽企業版 Linux） 建立了商業支持模式，德國供應商 SUSE 使用 SUSE Linux Enterprise Server（SLES）也提供了這種模式。",-1))]),n[41]||(n[41]=x("h3",{id:"比較-unix-和-linux",tabindex:"-1"},[i("比較 Unix 和 Linux "),x("a",{class:"header-anchor",href:"#比較-unix-和-linux","aria-label":"Permalink to “比較 Unix 和 Linux”"},"​")],-1)),n[42]||(n[42]=x("p",null,"到目前為止，我們已經瞭解了 Unix 的歷史以及 Linux 的興起，以及 GNU/自由軟件基金會對 Unix 的自由和開源替代品的支持。讓我們來看看這兩個操作系統之間的差異，它們有許多共同的傳統和許多相同的目標。",-1)),n[43]||(n[43]=x("p",null,"從用户體驗角度來看，兩者差不多！Linux 的很大吸引力在於操作系統在許多硬件體系結構（包括現代 PC）上的可用性以及類似使用 Unix 系統管理員和用户熟悉的工具的能力。",-1)),n[44]||(n[44]=x("p",null,"由於 POSIX 的標準和合規性，在 Unix 上編寫的軟件可以針對 Linux 操作系統進行編譯，通常只有少量的移植工作量。在很多情況下，Shell 腳本可以在 Linux 上直接使用。雖然一些工具在 Unix 和 Linux 之間有着略微不同的標誌或命令列選項，但許多工具在兩者上都是相同的。",-1)),x("p",null,[n[19]||(n[19]=i("一方面要注意的是，macOS 硬件和操作系統作為主要針對 Linux 的開發平台的流行可能歸因於類 BSD 的 macOS 操作系統。許多用於 Linux 系統的工具和腳本可以在 macOS 終端內輕鬆工作。Linux 上的許多開源軟件組件都可以通過 ",-1)),u(t,{href:"https://brew.sh/"},{default:l(()=>[...n[18]||(n[18]=[i("Homebrew",-1)])]),_:1}),n[20]||(n[20]=i(" 等工具輕鬆獲得。",-1))]),n[45]||(n[45]=x("p",null,"Linux 和 Unix 之間的其他差異主要與許可模式有關：開源與專有許可軟件。另外，在 Unix 發行版中缺少一個影響軟件和硬件供應商的通用內核。對於 Linux，供應商可以為特定的硬件設備創建設備驅動程序，並期望在合理的範圍內它可以在大多數發行版上運行。由於 Unix 家族的商業和學術分支，供應商可能必須為 Unix 的變體編寫不同的驅動程序，並且需要許可和其他相關的權限才能訪問 SDK 或軟件的分發模型，以跨越多個二進制設備驅動程序的 Unix 變體。",-1)),n[46]||(n[46]=x("p",null,"隨着這兩個社區在過去十年中的成熟，Linux 的許多優點已經在 Unix 世界中被採用。當開發人員需要來自不屬於 Unix 的 GNU 程序的功能時，許多 GNU 實用程序可作為 Unix 系統的附件提供。例如，IBM 的 AIX 為 Linux 應用程序提供了一個 AIX Toolbox，其中包含數百個 GNU 軟件包（如 Bash、 GCC、 OpenLDAP 和許多其他軟件包），這些軟件包可添加到 AIX 安裝包中以簡化 Linux 和基於 Unix 的 AIX 系統之間的過渡。",-1)),n[47]||(n[47]=x("p",null,"專有的 Unix 仍然活着而且還不錯，許多主要供應商承諾支持其當前版本，直到 2020 年。不言而喻，Unix 還會在可預見的將來一直出現。此外，Unix 的 BSD 分支是開源的，而 NetBSD、 OpenBSD 和 FreeBSD 都有強大的用户基礎和開源社區，它們可能不像 Linux 那樣顯眼或活躍，但在最近的服務器報告中，在 Web 服務等領域它們遠高於專有 Unix 的數量。",-1)),n[48]||(n[48]=x("p",null,[i("Linux 已經顯示出其超越 Unix 的顯著優勢在於其在大量硬件平台和設備上的可用性。"),x("ruby",null,[i("樹莓派"),x("rt",null,"Raspberry Pi")]),i("受到業餘愛好者的歡迎，它是由 Linux 驅動的，為運行 Linux 的各種物聯網設備打開了大門。我們已經提到了 Android 設備，汽車（包括 Automotive Grade Linux）和智能電視，其中 Linux 佔有巨大的市場份額。這個星球上的每個雲提供商都提供運行 Linux 的虛擬服務器，而且當今許多最受歡迎的原生雲架構都是基於 Linux 的，無論你是在談論容器運行時還是 Kubernetes，或者是許多正在流行的無服務器平台。")],-1)),n[49]||(n[49]=x("p",null,"其中一個最顯著的代表 Linux 的優勢是近年來微軟的轉變。如果你十年前告訴軟件開發人員，Windows 操作系統將在 2016 年“運行 Linux”，他們中的大多數人會歇斯底里地大笑。 但是 Windows Linux 子系統（WSL）的存在和普及，以及最近宣佈的諸如 Docker 的 Windows 移植版，包括 LCOW（Windows 上的 Linux 容器）支持等功能都證明了 Linux 在整個軟件世界中所產生的影響 —— 而且顯然還會繼續存在。",-1)),n[50]||(n[50]=x("hr",null,null,-1)),x("p",null,[n[22]||(n[22]=i("via: ",-1)),u(t,{href:"https://opensource.com/article/18/5/differences-between-linux-and-unix"},{default:l(()=>[...n[21]||(n[21]=[i("https://opensource.com/article/18/5/differences-between-linux-and-unix",-1)])]),_:1})]),x("p",null,[n[27]||(n[27]=i("作者：",-1)),u(t,{href:"https://opensource.com/users/estesp"},{default:l(()=>[...n[23]||(n[23]=[i("Phil Estes",-1)])]),_:1}),n[28]||(n[28]=i(" 選題：",-1)),u(t,{href:"https://github.com/lujun9972"},{default:l(()=>[...n[24]||(n[24]=[i("lujun9972",-1)])]),_:1}),n[29]||(n[29]=i(" 譯者：",-1)),u(t,{href:"https://github.com/MjSeven"},{default:l(()=>[...n[25]||(n[25]=[i("MjSeven",-1)])]),_:1}),n[30]||(n[30]=i(" 校對：",-1)),u(t,{href:"https://github.com/wxy"},{default:l(()=>[...n[26]||(n[26]=[i("wxy",-1)])]),_:1})]),x("p",null,[n[33]||(n[33]=i("本文由 ",-1)),u(t,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...n[31]||(n[31]=[i("LCTT",-1)])]),_:1}),n[34]||(n[34]=i(" 原創編譯，",-1)),u(t,{href:"https://linux.cn/"},{default:l(()=>[...n[32]||(n[32]=[i("Linux中國",-1)])]),_:1}),n[35]||(n[35]=i(" 榮譽推出",-1))])])}const C=s(U,[["render",d]]);export{D as __pageData,C as default};
